#!/usr/bin/env python3
"""closures-passed-to-array-methods.py <seed> [ts|js]: a closure written at the call of an array method may stay in the caller's frame, and is copied to the heap only where the method turns out not to be the built-in one. WHOEVER GETS A FRAME's CLOSURE UNCOPIED HOLDS A DANGLING CELL. Sites `x.map(f)`, filter, flatMap, find, findLast, reduce, reduceRight, sort-likes .. with the closure written at the site, in cold text, ALSO ONE THAT KEEPS ITSELF BY ITS OWN NAME ON THE PASSING ROAD, capturing values of every kind (numbers, strings, objects, this, parameters, nothing, many), in plain | async | generator functions, methods, arrows, under try, in loops, in tail position and not, with a second argument; RECEIVERS: arrays as made (the passing road), heirs of Array with and without an override, arrays with an own method, plain objects with the method, a getter that yields the method, a proxy, null. THE OVERRIDES KEEP WHAT THEY ARE HANDED: in a global list, in an object, in a Map, in a closure of their own, in a promise's reaction, by returning it, by throwing it; they call it at once, twice, not at all; they call the site again. THEN THE STACK IS TRODDEN DOWN (a deep recursion that writes many locals), the heap is collected, and every kept closure is called, compared with itself and asked for its name and length. As plain Bun."""
import random, sys
seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
TS = (sys.argv[2] if len(sys.argv) > 2 else 'js') == 'ts'
R = random.Random(seed)
A = ': any' if TS else ''
out = []; w = out.append
w('// generated by closures-passed-to-array-methods.py %d' % seed)
if TS: w('declare const console: { log(...values: unknown[]): void };')
w('const kept%s = []; const box%s = { f: null }; const byName = new Map(); let inner%s = null; const lines%s = [];' % (': any[]' if TS else '', A, A, ': string[]' if TS else ''))
w('const show = (v%s)%s => { try { return v === undefined ? "u" : typeof v === "function" ? "fn" : typeof v === "object" && v !== null ? JSON.stringify(v) : String(v); } catch (e) { return "?"; } };' % (A, ': string' if TS else ''))
w('function tread(n%s, a%s, b%s, c%s)%s { const p = a * 3 + 1, q = b * 5 + 2, r = c * 7 + 3, s = p ^ q, t = q ^ r, u = r ^ p, v = [p, q, r], o = { s, t, u }; if (n <= 0) return p + q + r + s + t + u + v.length + o.s; return (tread(n - 1, q & 1023, r & 1023, p & 1023) + s + t + u + v[0] + o.t) & 0xffff; }' % ((': number',) * 4 + (': number',) if TS else ('',) * 5))
w('const collect = () => { const g%s = globalThis; if (typeof g.fullGC === "function") g.fullGC(); else if (g.Bun) g.Bun.gc(true); let junk = []; for (let i = 0; i < 2000; i++) junk.push({ i, s: "j" + i, a: [i] }); return junk.length; };' % A)
KEEP = ['kept.push(f);', 'box.f = f; kept.push(box.f);', 'byName.set("k" + kept.length, f); kept.push(byName.get("k" + kept.length));', 'inner = () => f; kept.push(inner());', 'Promise.resolve(f).then(g => { kept.push(g); });', 'kept.push(f); kept.push(f);', 'kept.push(f.bind(null));', 'kept.push(f); f.tag = kept.length;' if not TS else 'kept.push(f); (f as any).tag = kept.length;']
THEN = ['return f(1, 0, this);', 'return [f(1, 0, this), f(2, 1, this)];', 'return f;', 'return undefined;', 'throw f;', 'return "kept";', 'return [f];', 'return { f };']
METHODS = [('map', 1), ('filter', 1), ('flatMap', 1), ('find', 1), ('findLast', 1), ('reduce', 2), ('reduceRight', 2), ('findIndex', 1), ('some', 1), ('every', 1), ('forEach', 1), ('sort', 1), ('toSorted', 1)]
n = 0
receivers = []
for m, _ in METHODS:
    for k in range(3):
        keep, then = R.choice(KEEP), R.choice(THEN); name = 'r_%s_%d' % (m, k)
        form = R.randrange(6)
        if TS and form == 0 and m == 'every': form = 1
        body = '(f%s, extra%s)%s { %s %s }' % (A, '?: any' if TS else '', A, keep, then)
        if form == 0: w('class H_%s extends Array { %s%s }' % (name, m, body)); make = 'H_%s.from([1, 2, 3])' % name if not TS else '(H_%s as any).from([1, 2, 3])' % name
        elif form == 1: make = '({ %s%s })' % (m, body)
        elif form == 2: make = 'Object.assign([1, 2, 3], { %s%s })' % (m, body)
        elif form == 3: make = '({ get %s() { return function (%sf%s, extra%s)%s { %s %s }; } })' % (m, 'this: any, ' if TS else '', A, '?: any' if TS else '', A, keep, then)
        elif form == 4: make = 'new Proxy([1, 2, 3], { get(t%s, key%s, r%s) { return key === "%s" ? function (%sf%s)%s { %s %s } : Reflect.get(t, key, r); } })' % (A, A, A, m, 'this: any, ' if TS else '', A, A, keep, then)
        else: make = 'Object.setPrototypeOf([1, 2, 3], { __proto__: Array.prototype, %s%s })' % (m, body)
        w('const %s = ()%s => %s;' % (name, A, make)); receivers.append((m, name))
CAPTURE = [('', 'v'), ('const k = n * 2;', 'v + k'), ('const s = "s" + n;', 's + v'), ('const o = { n };', 'o.n + v'), ('const k = n, l = n + 1, m2 = n + 2, p = "p" + n;', 'k + l + m2 + p + v'), ('', 'n + v'), ('const a = [n, n + 1];', 'a[1] + v'), ('const k = n * 0.5;', 'k + v'), ('const g = () => n;', 'g() + v'), ('const big = BigInt(n);', 'String(big) + v')]
sites = []
for i in range(40):
    m, arity = R.choice(METHODS); pre, expr = R.choice(CAPTURE)
    params = '(acc%s, v%s)' % (A, A) if arity == 2 else '(v%s)' % A
    if m in ('sort', 'toSorted'): params = '(v%s, w2%s)' % (A, A); 
    fn = R.choice(['%s => %s' % (params, expr), '%s => { return %s; }' % (params, expr), 'function %s { return %s; }' % (params, expr), 'function self%s%s { if (kept.length < 400) kept.push(self); return %s; }' % (params, A, expr), 'function self%s%s { box.f = self; return %s; }' % (params, A, expr)])
    args = fn + (', 0' if arity == 2 else R.choice(['', '', ', n', ', undefined']))
    call = 'x.%s(%s)' % (m, args)
    kind = R.randrange(9); name = 'site%d' % i; P = '(x%s, n%s)' % (A, ': number' if TS else '')
    if kind == 0: w('function %s%s%s { %s const r = %s; return show(r); }' % (name, P, A, pre, call))
    elif kind == 1: w('function %s%s%s { %s return %s; }' % (name, P, A, pre, call))
    elif kind == 2: w('function %s%s%s { %s try { const r = %s; return show(r); } catch (e) { kept.push(e); return "caught " + typeof e; } }' % (name, P, A, pre, call))
    elif kind == 3: w('async function %s%s%s { %s const r = %s; await null; return show(r); }' % (name, P, ': Promise<any>' if TS else '', pre, call))
    elif kind == 4: w('function* gen%s%s%s { %s const r = %s; yield show(r); }\nconst %s = (x%s, n%s)%s => [...gen%s(x, n)][0];' % (name, P, A, pre, call, name, A, ': number' if TS else '', A, name))
    elif kind == 5: w('const %s = %s%s => { %s const r = %s; return show(r); };' % (name, P, A, pre, call))
    elif kind == 6: w('function %s%s%s { %s let r%s; for (let i = 0; i < 2; i++) r = %s; return show(r); }' % (name, P, A, pre, A, call))
    elif kind == 7: w('const holder%d = { m%s%s { %s const r = %s; return show(r) + typeof this; } };\nconst %s = (x%s, n%s)%s => holder%d.m(x, n);' % (i, P, A, pre, call, name, A, ': number' if TS else '', A, i))
    else: w('function %s%s%s { %s const r = %s, r2 = %s; return show(r) + show(r2); }' % (name, P, A, pre, call, call))
    sites.append((name, m))
w('async function main() {')
for name, m in sites:
    rs = [r for mm, r in receivers if mm == m]
    for r in ['() => [1, 2, 3]'] + rs + ['() => [1, 2, 3]']:
        w('  { let said; try { said = show(await %s((%s)(), %d)); } catch (e) { kept.push(e); said = "THROWS " + typeof e; } tread(60, 1, 2, 3); lines.push("%s %s: " + said); }' % (name, r, R.randrange(1, 9), name, r.replace('"', "'")[:24]))
w('  await null; await null; tread(200, 3, 2, 1); collect(); tread(200, 1, 1, 1);')
w('  for (const line of lines) console.log(line);')
w('  kept.forEach((f, i) => { let s; try { s = typeof f !== "function" ? show(f) : show(f(10, 20)) + " " + f.length + " " + JSON.stringify(f.name) + " " + (f === kept[i]) + " " + show(f.tag); } catch (e) { s = "THROWS " + (e%s).name; } console.log("kept " + i + ": " + s); });' % (' as Error' if TS else ''))
w('  console.log("the same twice: " + kept.map((f, i) => (i && f === kept[i - 1] ? 1 : 0)).join(""));')
w('}')
w('main();')
print('\n'.join(out))
